import pytest
import click
from click.testing import CliRunner


@pytest.fixture
def runner():
    return CliRunner()


def test_deprecated_option(runner):
    @click.command()
    @click.option("--old-name", deprecated=True, help="This is the old name.")
    @click.option("--new-name", help="This is the new name.")
    def cli(old_name, new_name):
        if old_name:
            click.echo(f"Old name used: {old_name}")
        if new_name:
            click.echo(f"New name used: {new_name}")

    # Test using the deprecated option
    result = runner.invoke(cli, ["--old-name", "value"])
    assert "Deprecated: Option '--old-name' is deprecated." in result.output
    assert "Old name used: value" in result.output
    assert result.exit_code == 0

    # Test using the new option
    result = runner.invoke(cli, ["--new-name", "value"])
    assert "Deprecated: Option '--old-name' is deprecated." not in result.output
    assert "New name used: value" in result.output
    assert result.exit_code == 0

    # Test help message includes deprecation warning
    result = runner.invoke(cli, ["--help"])
    assert "Deprecated: Option '--old-name' is deprecated." in result.output
    assert "--old-name TEXT  [deprecated] This is the old name." in result.output
    assert "--new-name TEXT  This is the new name." in result.output

    # Test using both deprecated and new option (should warn for deprecated)
    @click.command()
    @click.option("--count", deprecated=True, help="Old count option.")
    @click.option("--greetings-count", help="New greetings count option.")
    def hello(count, greetings_count):
        if count is not None:
            click.echo(f"Count: {count}")
        if greetings_count is not None:
            click.echo(f"Greetings Count: {greetings_count}")

    result = runner.invoke(hello, ["--count", "5", "--greetings-count", "10"])
    assert "Deprecated: Option '--count' is deprecated." in result.output
    assert "Count: 5" in result.output
    assert "Greetings Count: 10" in result.output
    assert result.exit_code == 0

