import pytest
import click
from click.testing import CliRunner
from click.shell_completion import BashComplete
from click.shell_completion import ZshComplete
from click.shell_completion import FishComplete


@pytest.fixture
def runner():
    return CliRunner()


@pytest.mark.parametrize("shell", ["bash", "zsh", "fish"])
def test_file_option_completion_closes_file(runner, shell, tmp_path):
    test_file = tmp_path / "test.txt"
    test_file.write_text("hello")

    @click.group()
    @click.option(
        "--config-file",
        default=str(test_file),
        type=click.File(mode="r"),
        help="A config file.",
    )
    def cli(config_file):
        pass

    # Simulate shell completion environment variables
    env = {
        f"_{cli.name.upper()}_COMPLETE": f"{shell}_complete",
        "COMP_WORDS": "cli --config-file",
        "COMP_CWORD": "2",
        "COMP_POINT": "18",
    }
    if shell == "zsh":
        env["_CLI_COMPLETE_LINE"] = "cli --config-file "
        env["_CLI_COMPLETE_POINT"] = "18"
    elif shell == "fish":
        env["_CLI_COMPLETE_LINE"] = "cli --config-file "
        env["_CLI_COMPLETE_POINT"] = "18"

    # Run completion and check for ResourceWarning
    with pytest.warns(ResourceWarning) as record:
        result = runner.invoke(cli, ["--completion", f"{shell}_complete"], env=env)

    # The bug is that the file is not closed, leading to a ResourceWarning.
    # If the bug is fixed, there should be no ResourceWarning.
    assert not record.list, "ResourceWarning was raised, file was not closed."
    assert result.exit_code == 0

import pytest
from jinja2 import Environment
from jinja2 import TemplateSyntaxError


def test_namespace_multi_variable_assignment(env):
    template = """
        {% set full = namespace(id="", prev_id="") -%}
        {% for id in endpoints recursive %}
          {% set full.prev_id, full.id = full.id, full.id + "/" + id -%}
        {% endfor -%}
        {{ full.id }}
    """
    env = Environment()
    tmpl = env.from_string(template)
    # The bug causes a TemplateSyntaxError during compilation.
    # If the bug is fixed, this should render correctly.
    assert tmpl.render(endpoints=["a", "b"]) == "/a/b"

import pytest
from jinja2 import Environment
from jinja2 import DictLoader
from jinja2.ext import i18n


class TestI18nBlockPGettext:
    def test_block_pgettext(self):
        env = Environment(
            loader=DictLoader(
                {
                    "main": """
                        {% pgettext "my_context" %}Hello{% endpgettext %}
                        {% pgettext "another_context" %}World{% endpgettext %}
                    """
                }
            ),
            extensions=[i18n],
        )

        # Mock the gettext functions to observe calls
        calls = []

        def mock_pgettext(context, message):
            calls.append(("pgettext", context, message))
            return f"[{context}]{message}"

        env.install_gettext_callables(lambda x: x, lambda s, p, n: s, mock_pgettext, lambda c, s, p, n: s)

        template = env.get_template("main")
        result = template.render()

        assert result.strip() == "[my_context]Hello\n[another_context]World"
        assert calls == [
            ("pgettext", "my_context", "Hello"),
            ("pgettext", "another_context", "World"),
        ]

    def test_block_pgettext_with_variables(self):
        env = Environment(
            loader=DictLoader(
                {
                    "main": """
                        {% pgettext "greeting" name="John" %}Hello, %(name)s!{% endpgettext %}
                    """
                }
            ),
            extensions=[i18n],
        )

        calls = []

        def mock_pgettext(context, message):
            calls.append(("pgettext", context, message))
            return f"[{context}]{message}"

        env.install_gettext_callables(lambda x: x, lambda s, p, n: s, mock_pgettext, lambda c, s, p, n: s)

        template = env.get_template("main")
        result = template.render()

        assert result.strip() == "[greeting]Hello, John!"
        assert calls == [
            ("pgettext", "greeting", "Hello, %(name)s!"),
        ]

    def test_block_pgettext_with_pluralize(self):
        env = Environment(
            loader=DictLoader(
                {
                    "main": """
                        {% pgettext "item_count" num=1 %}One item{% pluralize %}{{ num }} items{% endpgettext %}
                        {% pgettext "item_count" num=5 %}One item{% pluralize %}{{ num }} items{% endpgettext %}
                    """
                }
            ),
            extensions=[i18n],
        )

        calls = []

        def mock_npgettext(context, singular, plural, n):
            calls.append(("npgettext", context, singular, plural, n))
            if n == 1:
                return f"[{context}]{singular}"
            return f"[{context}]{plural}"

        env.install_gettext_callables(lambda x: x, lambda s, p, n: s, lambda c, m: m, mock_npgettext)

        template = env.get_template("main")
        result = template.render()

        expected = "[item_count]One item\n[item_count]5 items"
        assert result.strip() == expected
        assert calls == [
            ("npgettext", "item_count", "One item", "%(num)s items", 1),
            ("npgettext", "item_count", "One item", "%(num)s items", 5),
        ]

